o (Rua Doutor Eugênio Prado)","osm_way_id":170768406,"nome_osm":"Rua Doutor Eugênio Prado","mao_unica":false,"sentido":"ambos","comprimento_m":79,"fonte_trecho":"Dec. 6.779/2018, art. 2º (logradouro inteiro)","verificado_em":"2026-10-11","valhalla_validado":true}$q$::jsonb, $q$2018-08-10$q$::timestamptz, null::timestamptz),
